-- Phase 10b task 1: legal texts as versioned rows. Generated by drizzle-kit,
-- then the seed was appended: version 1 of the privacy notice and the terms
-- in nl, en and fr, published, effective 2026-09-30, with the content of
-- packages/i18n/src/legal/{nl,en,fr}.ts as they were when this migration was
-- written (the LegalDocument as JSON). The shipped texts stay the fallback.
CREATE TABLE `legal_text` (
	`id` text PRIMARY KEY NOT NULL,
	`kind` text NOT NULL,
	`locale` text NOT NULL,
	`version` integer NOT NULL,
	`content` text NOT NULL,
	`effective_date` text NOT NULL,
	`status` text NOT NULL,
	`updated_by` text,
	`updated_at` integer NOT NULL,
	`published_by` text,
	`published_at` integer,
	FOREIGN KEY (`locale`) REFERENCES `language`(`code`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`updated_by`) REFERENCES `user`(`id`) ON UPDATE no action ON DELETE set null,
	FOREIGN KEY (`published_by`) REFERENCES `user`(`id`) ON UPDATE no action ON DELETE set null,
	CONSTRAINT "legal_text_kind_check" CHECK("kind" IN ('privacy', 'terms')),
	CONSTRAINT "legal_text_status_check" CHECK("status" IN ('draft', 'published')),
	CONSTRAINT "legal_text_version_check" CHECK("version" >= 1),
	CONSTRAINT "legal_text_effective_date_check" CHECK("effective_date" GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
	CONSTRAINT "legal_text_published_check" CHECK(("status" = 'published') = ("published_at" IS NOT NULL))
);
--> statement-breakpoint
CREATE UNIQUE INDEX `legal_text_version_uq` ON `legal_text` (`kind`,`locale`,`version`);--> statement-breakpoint
CREATE UNIQUE INDEX `legal_text_draft_uq` ON `legal_text` (`kind`,`locale`) WHERE "status" = 'draft';--> statement-breakpoint
CREATE INDEX `legal_text_published_idx` ON `legal_text` (`kind`,`locale`,`version`) WHERE "status" = 'published';--> statement-breakpoint
CREATE INDEX `legal_text_updated_by_idx` ON `legal_text` (`updated_by`);--> statement-breakpoint
CREATE INDEX `legal_text_published_by_idx` ON `legal_text` (`published_by`);
--> statement-breakpoint
INSERT INTO `legal_text` (`id`, `kind`, `locale`, `version`, `content`, `effective_date`, `status`, `updated_by`, `updated_at`, `published_by`, `published_at`) VALUES ('legal-privacy-nl-1', 'privacy', 'nl', 1, '{"sections":[{"blocks":["Dit privacybeleid beschrijft hoe SMOG & CO vzw persoonsgegevens verwerkt wanneer u de SMOG&Co-website, mobiele app, accounts, gedeelde lijsten, sponsoring en bijbehorende ondersteuning gebruikt (samen: de \"Dienst\")."],"id":"scope","title":"Toepassingsgebied"},{"blocks":["SMOG & CO vzw, Arthur Goemaerelei 66, 2018 Antwerpen, België, O.N. 1009 954 991, is de verwerkingsverantwoordelijke. Privacyvragen kunt u sturen naar [info@smog.vlaanderen](mailto:info@smog.vlaanderen)."],"id":"controller","title":"Verwerkingsverantwoordelijke"},{"blocks":[{"list":["**Account en aanmelding:** naam, e-mailadres en of het bevestigd is, taal, rol, eventueel een profielfoto van Google (die uw browser rechtstreeks bij Google ophaalt wanneer ze getoond wordt), sessies (met IP-adres en browser- of appgegevens) en tijdstippen. Een wachtwoord bewaren we alleen als onomkeerbare hash; van een passkey bewaren we alleen de publieke sleutel. Meldt u zich aan met Google of Apple, dan ontvangen we van hen een account-ID, uw naam en uw e-mailadres.","**Gebruik zonder account:** favorieten, lijsten, recente zoekopdrachten, voorkeuren en uw analyticskeuze blijven op uw apparaat. Ze verlaten uw apparaat niet, tenzij u na het aanmelden kiest om ze in uw account te importeren, en behalve de optionele analytics hieronder (bijvoorbeeld welk gebaar u bekeek of bewaarde).","**Leerfuncties:** favoriete gebaren, lijsten, lijstbeschrijvingen, deellinks en hun rechten (bekijken of bewerken). Recente zoektermen blijven lokaal op uw apparaat.","**Sponsoring:** contactnaam, sponsor- of bedrijfsnaam, e-mail, gekozen gebaren, weergavenaam, optioneel logo, voorbeeld- en eindvideo''s, status, betaalreferentie en looptijd.","**Facturatie:** factuurnaam, btw- of ondernemingsnummer en factuur-e-mailadres wanneer u een factuur vraagt. Mollie verwerkt de betaalgegevens; SMOG&Co ontvangt geen volledige kaart- of bankgegevens.","**Technische gegevens:** IP-adres, apparaat-, browser- en appgegevens, beveiligingslogs, foutinformatie en gegevens die nodig zijn voor video- en netwerklevering. Bij aanmelden, registreren, wachtwoordherstel en andere formulieren (zoals het aanvragen van een aanmeldcode of -link) controleert Cloudflare Turnstile of het verzoek van een mens komt.","**Toestemmingsgeschiedenis:** bent u aangemeld, dan bewaren we uw analyticskeuzes (ja of nee, tijdstip en beleidsversie), zodat we kunnen aantonen welke keuze geldt.","**Optionele analytics:** alleen na toestemming: schermpad, platform, beperkte gebeurtenisgegevens, gebaar-ID''s, resultaat- en categorietellingen, lengte van een zoekopdracht en voltooid afspelen, met uw IP-adres en browser- of appgegevens (zie Analytics en identificatie). We sturen geen zoektermen, namen of e-mailadressen en maken geen sessie-opnames."]}],"id":"data","title":"Welke gegevens wij verwerken"},{"blocks":[{"list":["**Overeenkomst:** accounts, favorieten, lijsten, gedeelde lijsten, sponsoring, betalingen, videoverwerking en transactionele communicatie leveren.","**Wettelijke verplichting:** boekhouding, facturatie, fiscale verplichtingen en beantwoording van geldige wettelijke verzoeken.","**Gerechtvaardigd belang:** beveiliging, fraude- en misbruikpreventie (zoals Turnstile en limieten op het aantal verzoeken), beheer, foutdiagnose en verbetering van de betrouwbaarheid van de Dienst. U kunt hiertegen bezwaar maken.","**Toestemming:** optionele OpenPanel-analytics. U kunt weigeren of later intrekken zonder dat basisfuncties wegvallen."]}],"id":"purposes","title":"Doeleinden en rechtsgronden"},{"blocks":["Alleen bevoegde medewerkers en dienstverleners die de Dienst ondersteunen krijgen toegang voor zover dat nodig is:",{"list":["**Cloudflare:** hosting van de website en de API (Workers), de database (D1), bestandsopslag zoals sponsorlogo''s (R2), tijdelijke gegevens (KV), wachtrijen (Queues), het renderen van sponsorvideo''s met naam en logo (Workflows, Containers), het verzenden van e-mails (Email) en misbruikpreventie (Turnstile). [Privacybeleid](https://www.cloudflare.com/privacypolicy/)","**Better Auth:** open-source aanmeldsoftware die wij zelf binnen onze Cloudflare-omgeving draaien. Er gaan daarvoor geen gegevens naar een aparte aanbieder.","**Mux:** opslag, verwerking en streaming van gebaren- en sponsorvideo''s. [Privacybeleid](https://www.mux.com/privacy)","**Mollie:** gehoste betaalafhandeling en betaalstatus. [Privacybeleid](https://www.mollie.com/legal/privacy)","**Expo:** distributie en updates van de mobiele app. [Privacybeleid](https://expo.dev/privacy)","**Google en Apple:** wanneer u kiest om u met uw Google- of Apple-account aan te melden. Hebt u een profielfoto van Google, dan haalt uw browser die bij elke weergave rechtstreeks bij Google op; Google ziet dan uw IP-adres en browsergegevens. [Google](https://policies.google.com/privacy) · [Apple](https://www.apple.com/legal/privacy/)","**OpenPanel:** zelfgehoste analysesoftware op analytics.zias.be, uitsluitend na analytics-toestemming. De OpenPanel-cloud wordt niet gebruikt voor onze gebeurtenisdata."]},"Persoonsgegevens worden niet verkocht. We delen ze alleen op grond van een overeenkomst, wettelijke verplichting of ander geldig juridisch kader."],"id":"recipients","title":"Ontvangers en dienstverleners"},{"blocks":["Analytics staat standaard uit. Na toestemming stuurt de website gebeurtenissen via onze eigen server door naar onze zelfgehoste OpenPanel-installatie, zonder scripts of cookies van derden. Onze server geeft daarbij uw IP-adres en browsergegevens (user agent) door; OpenPanel leidt daaruit een pseudoniem apparaatprofiel en een benaderende locatie (land en regio) af. Onze server bewaart die gegevens daarvoor zelf niet. De app stuurt gebeurtenissen rechtstreeks naar dezelfde OpenPanel-installatie, met een pseudonieme apparaat-ID. Na aanmelding wordt het profiel alleen aan uw gebruikers-ID gekoppeld; uw naam en e-mailadres gaan niet naar analytics. Bij uitloggen of intrekken wordt de analytics-identiteit gewist. Intrekken stopt nieuwe metingen; eerder rechtmatig verzamelde gegevens worden daardoor niet automatisch verwijderd. U kunt verwijdering aanvragen via ons contactadres."],"id":"analytics","title":"Analytics en identificatie"},{"blocks":["SMOG & Co volgt gebruikers niet over apps of websites van andere bedrijven heen. We gebruiken analyticsgegevens niet voor gerichte advertenties of advertentiemeting en delen analyticsgegevens niet met data brokers."],"id":"no-tracking","title":"Geen tracking of advertenties"},{"blocks":[{"list":["Noodzakelijke cookies houden uw sessie actief wanneer u aangemeld bent en onthouden uw taal en thema. Daarnaast zetten we tijdens onderhoud een technische cookie voor beheerders, zodat zij de site kunnen blijven gebruiken.","Lokale opslag bewaart onder meer favorieten en lijsten zonder account, recente zoekopdrachten, voorkeuren, appcache en uw analyticskeuze. Een keuze die u aangemeld maakte, blijft ook op het apparaat, maar geldt alleen voor uw account: wie het apparaat daarna zonder account gebruikt, krijgt de vraag opnieuw.","Na analytics-toestemming kan de app lokale identificatie- en wachtrijgegevens bewaren om gebeurtenissen af te leveren. De website bewaart alleen tijdens het aanmelden een tijdelijke markering in de sessie-opslag van uw browser, zodat een voltooide aanmelding één keer wordt geteld."]},"U kunt uw analyticskeuze hieronder op elk moment wijzigen:",{"consentControl":true}],"id":"cookies","title":"Cookies en lokale opslag"},{"blocks":[{"list":["Accountgegevens, favorieten, lijsten en uw toestemmingsgeschiedenis blijven bewaard zolang uw account bestaat of totdat u ze verwijdert.","Beheerlogs worden maximaal 3 jaar bewaard.","Een sessie verloopt 7 dagen nadat u de Dienst het laatst gebruikte, of meteen wanneer u zich afmeldt. Aanmeldcodes en aanmeldlinks zijn eenmalig en 5 minuten geldig; links om uw e-mailadres te bevestigen of uw wachtwoord te herstellen 1 uur. Verlopen sessies, codes en links worden binnen 30 dagen gewist.","Niet-betaalde sponsoraanvragen worden na 24 uur geannuleerd. Onderliggende technische bestanden kunnen volgens operationele back-up- en opschooncycli later verdwijnen.","Betaal-, sponsor- en factuurgegevens worden bewaard zolang dat nodig is voor de overeenkomst en maximaal 10 jaar wanneer de Belgische boekhoud- of fiscale regels dat vereisen.","Analyticsgegevens worden bewaard volgens de ingestelde bewaartermijn van onze OpenPanel-installatie en niet langer dan nodig voor productanalyse."]}],"id":"retention","title":"Bewaartermijnen"},{"blocks":["Op de [accountpagina](/account) kunt u uw account verwijderen. Dat verwijdert meteen uw account, sessies, aanmeldmethodes en passkeys, favorieten, eigen lijsten met hun deellinks en uw toestemmingsgeschiedenis. In beheerlogs wordt u als uitvoerder losgekoppeld; beheerlogs over uw account blijven tot het einde van hun bewaartermijn bestaan. U wordt op elk apparaat afgemeld en de gegevens op het gebruikte apparaat worden gewist. Sponsor-, betaal- en factuurgegevens zijn niet aan uw account gekoppeld en worden bewaard zolang de wet dat vereist (zie Bewaartermijnen). Back-ups en gegevens bij afzonderlijke dienstverleners kunnen hun eigen verwijdercyclus volgen."],"id":"deletion","title":"Accountverwijdering"},{"blocks":["Onder de GDPR kunt u, afhankelijk van de omstandigheden, inzage, rectificatie, wissing, beperking, overdraagbaarheid of bezwaar vragen. U kunt toestemming altijd intrekken en een klacht indienen bij een toezichthouder. De [accountpagina](/account) biedt een machineleesbare export (JSON) en accountverwijdering. Voor andere verzoeken mailt u [info@smog.vlaanderen](mailto:info@smog.vlaanderen). We kunnen informatie vragen om uw identiteit te verifiëren."],"id":"rights","title":"Uw rechten"},{"blocks":["Sommige dienstverleners kunnen persoonsgegevens buiten de Europese Economische Ruimte verwerken. Waar nodig gebruiken we een adequaatheidsbesluit, standaardcontractbepalingen of een ander rechtsgeldig doorgiftemechanisme en passende aanvullende beveiligingsmaatregelen."],"id":"transfers","title":"Internationale doorgiften"},{"blocks":["We gebruiken passende technische en organisatorische maatregelen, waaronder toegangsbeperking, versleutelde verbindingen, gehashte wachtwoorden en afgeschermde secrets. Geen systeem is volledig risicoloos. Bij een meldingsplichtig incident informeren we de bevoegde autoriteit en, wanneer vereist, betrokken personen."],"id":"security","title":"Beveiliging en incidenten"},{"blocks":["In België kan een kind vanaf 13 jaar zelf toestemming geven voor een rechtstreeks aangeboden online dienst. Is volgens het toepasselijke recht toestemming van een ouder of voogd nodig, dan moet die worden verkregen. Neem contact op wanneer u denkt dat gegevens van een kind onrechtmatig zijn verwerkt."],"id":"children","title":"Kinderen"},{"blocks":["We kunnen dit beleid bijwerken wanneer de Dienst, leveranciers of wetgeving wijzigen. De datum bovenaan wordt aangepast en bij belangrijke wijzigingen informeren we gebruikers in de app of via een passend kanaal. Waar nodig vragen we opnieuw toestemming."],"id":"changes","title":"Wijzigingen"},{"blocks":[{"lines":["SMOG & CO vzw","Arthur Goemaerelei 66, 2018 Antwerpen, België","E-mail: [info@smog.vlaanderen](mailto:info@smog.vlaanderen)","Tel.: 03/216 29 90","O.N. 1009 954 991"]},"U kunt ook een klacht indienen bij de [Belgische Gegevensbeschermingsautoriteit](https://www.gegevensbeschermingsautoriteit.be/burger/acties/klacht-indienen) of bij uw lokale toezichthouder."],"id":"contact","title":"Contact en klacht"}],"title":"Privacybeleid"}', '2026-09-30', 'published', NULL, 1790726400000, NULL, 1790726400000);
--> statement-breakpoint
INSERT INTO `legal_text` (`id`, `kind`, `locale`, `version`, `content`, `effective_date`, `status`, `updated_by`, `updated_at`, `published_by`, `published_at`) VALUES ('legal-privacy-en-1', 'privacy', 'en', 1, '{"sections":[{"blocks":["This privacy policy describes how SMOG & CO vzw processes personal data when you use the SMOG&Co website, mobile app, accounts, shared lists, sponsorship and related support (together: the \"Service\")."],"id":"scope","title":"Scope"},{"blocks":["SMOG & CO vzw, Arthur Goemaerelei 66, 2018 Antwerp, Belgium, company number 1009 954 991, is the data controller. You can send privacy questions to [info@smog.vlaanderen](mailto:info@smog.vlaanderen)."],"id":"controller","title":"Data controller"},{"blocks":[{"list":["**Account and sign-in:** name, email address and whether it is verified, language, role, a profile picture from Google if any (which your browser fetches directly from Google whenever it is shown), sessions (with IP address and browser or app details) and timestamps. A password is only stored as an irreversible hash; for a passkey we only store its public key. If you sign in with Google or Apple, they send us an account ID, your name and your email address.","**Use without an account:** favorites, lists, recent searches, preferences and your analytics choice stay on your device. They do not leave your device unless, after signing in, you choose to import them into your account, except for the optional analytics below (for example which gesture you viewed or saved).","**Learning features:** favorite gestures, lists, list descriptions, share links and their rights (view or edit). Recent search terms stay locally on your device.","**Sponsorship:** contact name, sponsor or company name, email, chosen gestures, display name, optional logo, preview and final videos, status, payment reference and term.","**Invoicing:** invoice name, VAT or company number and invoice email address when you ask for an invoice. Mollie processes the payment details; SMOG&Co does not receive full card or bank details.","**Technical data:** IP address, device, browser and app details, security logs, error information and data needed to deliver video and network traffic. When you sign in, sign up, reset your password or use other forms (such as asking for a sign-in code or link), Cloudflare Turnstile checks that the request comes from a human.","**Consent history:** when you are signed in, we keep your analytics choices (yes or no, time and policy version), so we can show which choice applies.","**Optional analytics:** only with consent: screen path, platform, limited event data, gesture IDs, result and category counts, the length of a search and completed playback, with your IP address and browser or app details (see Analytics and identification). We do not send search terms, names or email addresses and do not record sessions."]}],"id":"data","title":"What data we process"},{"blocks":[{"list":["**Contract:** providing accounts, favorites, lists, shared lists, sponsorship, payments, video processing and transactional communication.","**Legal obligation:** bookkeeping, invoicing, tax obligations and answering valid legal requests.","**Legitimate interest:** security, fraud and abuse prevention (such as Turnstile and limits on the number of requests), administration, error diagnosis and improving the reliability of the Service. You can object to this.","**Consent:** optional OpenPanel analytics. You can refuse or withdraw later without losing basic features."]}],"id":"purposes","title":"Purposes and legal bases"},{"blocks":["Only authorised staff and service providers that support the Service get access, as far as needed:",{"list":["**Cloudflare:** hosting of the website and the API (Workers), the database (D1), file storage such as sponsor logos (R2), temporary data (KV), queues (Queues), rendering sponsor videos with the name and logo (Workflows, Containers), sending email (Email) and abuse prevention (Turnstile). [Privacy policy](https://www.cloudflare.com/privacypolicy/)","**Better Auth:** open-source sign-in software that we run ourselves inside our Cloudflare environment. No data goes to a separate provider for it.","**Mux:** storage, processing and streaming of gesture and sponsor videos. [Privacy policy](https://www.mux.com/privacy)","**Mollie:** hosted payment processing and payment status. [Privacy policy](https://www.mollie.com/legal/privacy)","**Expo:** distribution and updates of the mobile app. [Privacy policy](https://expo.dev/privacy)","**Google and Apple:** when you choose to sign in with your Google or Apple account. If you have a Google profile picture, your browser fetches it directly from Google each time it is shown, so Google sees your IP address and browser details. [Google](https://policies.google.com/privacy) · [Apple](https://www.apple.com/legal/privacy/)","**OpenPanel:** self-hosted analytics software at analytics.zias.be, only with analytics consent. The OpenPanel cloud is not used for our event data."]},"Personal data is not sold. We only share it on the basis of a contract, a legal obligation or another valid legal framework."],"id":"recipients","title":"Recipients and service providers"},{"blocks":["Analytics is off by default. With consent, the website forwards events through our own server to our self-hosted OpenPanel installation, without third-party scripts or cookies. Our server passes on your IP address and browser details (user agent); OpenPanel derives a pseudonymous device profile and an approximate location (country and region) from them. Our server does not store that data for this purpose. The app sends events directly to the same OpenPanel installation, with a pseudonymous device ID. After you sign in, the profile is only linked to your user ID; your name and email address are not sent to analytics. Signing out or withdrawing consent clears the analytics identity. Withdrawing stops new measurements; data collected lawfully before is not deleted automatically. You can ask for its deletion at our contact address."],"id":"analytics","title":"Analytics and identification"},{"blocks":["SMOG & Co does not track users across apps or websites of other companies. We do not use analytics data for targeted advertising or advertising measurement and do not share analytics data with data brokers."],"id":"no-tracking","title":"No tracking or advertising"},{"blocks":[{"list":["Necessary cookies keep your session active when you are signed in and remember your language and theme. We also set a technical cookie for administrators during maintenance, so they can keep using the site.","Local storage keeps, among other things, favorites and lists without an account, recent searches, preferences, the app cache and your analytics choice. A choice you made while signed in also stays on the device, but it only applies to your account: whoever then uses the device without an account is asked again.","With analytics consent, the app may keep local identification and queue data to deliver events. The website only keeps a temporary marker in your browser''s session storage while you sign in, so a completed sign-in is counted once."]},"You can change your analytics choice below at any time:",{"consentControl":true}],"id":"cookies","title":"Cookies and local storage"},{"blocks":[{"list":["Account data, favorites, lists and your consent history are kept as long as your account exists or until you delete them.","Administration logs are kept for at most 3 years.","A session expires 7 days after you last used the Service, or at once when you sign out. Sign-in codes and sign-in links are single-use and valid for 5 minutes; links to verify your email address or reset your password for 1 hour. Expired sessions, codes and links are erased within 30 days.","Unpaid sponsorship requests are cancelled after 24 hours. Underlying technical files may disappear later, following operational backup and clean-up cycles.","Payment, sponsor and invoice data is kept as long as needed for the contract and for up to 10 years when Belgian accounting or tax rules require it.","Analytics data is kept according to the retention period set in our OpenPanel installation and no longer than needed for product analysis."]}],"id":"retention","title":"Retention periods"},{"blocks":["You can delete your account on the [account page](/account). This immediately deletes your account, sessions, sign-in methods and passkeys, favorites, your own lists with their share links and your consent history. In administration logs you are unlinked as the actor; administration logs about your account remain until the end of their retention period. You are signed out on every device and the data on the device you used is cleared. Sponsor, payment and invoice data is not linked to your account and is kept as long as the law requires (see Retention periods). Backups and data at separate service providers may follow their own deletion cycle."],"id":"deletion","title":"Account deletion"},{"blocks":["Under the GDPR you can, depending on the circumstances, ask for access, rectification, erasure, restriction, portability or object. You can always withdraw consent and lodge a complaint with a supervisory authority. The [account page](/account) offers a machine-readable export (JSON) and account deletion. For other requests, email [info@smog.vlaanderen](mailto:info@smog.vlaanderen). We may ask for information to verify your identity."],"id":"rights","title":"Your rights"},{"blocks":["Some service providers may process personal data outside the European Economic Area. Where needed, we use an adequacy decision, standard contractual clauses or another valid transfer mechanism and appropriate additional security measures."],"id":"transfers","title":"International transfers"},{"blocks":["We use appropriate technical and organisational measures, including access restriction, encrypted connections, hashed passwords and protected secrets. No system is completely free of risk. In case of a notifiable incident we inform the competent authority and, when required, the people concerned."],"id":"security","title":"Security and incidents"},{"blocks":["In Belgium, a child aged 13 or over can give consent themselves for an online service offered to them directly. If the applicable law requires the consent of a parent or guardian, it must be obtained. Contact us if you believe a child''s data has been processed unlawfully."],"id":"children","title":"Children"},{"blocks":["We may update this policy when the Service, suppliers or legislation change. The date at the top is updated, and we inform users of important changes in the app or through an appropriate channel. Where needed, we ask for consent again."],"id":"changes","title":"Changes"},{"blocks":[{"lines":["SMOG & CO vzw","Arthur Goemaerelei 66, 2018 Antwerp, Belgium","Email: [info@smog.vlaanderen](mailto:info@smog.vlaanderen)","Phone: +32 3 216 29 90","Company number 1009 954 991"]},"You can also lodge a complaint with the [Belgian Data Protection Authority](https://www.dataprotectionauthority.be) or with your local supervisory authority."],"id":"contact","title":"Contact and complaints"}],"title":"Privacy policy"}', '2026-09-30', 'published', NULL, 1790726400000, NULL, 1790726400000);
--> statement-breakpoint
INSERT INTO `legal_text` (`id`, `kind`, `locale`, `version`, `content`, `effective_date`, `status`, `updated_by`, `updated_at`, `published_by`, `published_at`) VALUES ('legal-privacy-fr-1', 'privacy', 'fr', 1, '{"sections":[{"blocks":["La présente politique de confidentialité décrit comment SMOG & CO vzw traite les données personnelles lorsque vous utilisez le site web SMOG&Co, l''application mobile, les comptes, les listes partagées, le parrainage et l''assistance associée (ensemble : le « Service »)."],"id":"scope","title":"Champ d''application"},{"blocks":["SMOG & CO vzw, Arthur Goemaerelei 66, 2018 Anvers, Belgique, numéro d''entreprise 1009 954 991, est le responsable du traitement. Vous pouvez envoyer vos questions sur la vie privée à [info@smog.vlaanderen](mailto:info@smog.vlaanderen)."],"id":"controller","title":"Responsable du traitement"},{"blocks":[{"list":["**Compte et connexion :** nom, adresse e-mail et sa vérification, langue, rôle, éventuellement une photo de profil de Google (que votre navigateur récupère directement auprès de Google lorsqu''elle est affichée), sessions (avec l''adresse IP et les données du navigateur ou de l''application) et horodatages. Un mot de passe n''est conservé que sous forme de hachage irréversible ; d''une clé d''accès (passkey), nous ne conservons que la clé publique. Si vous vous connectez avec Google ou Apple, ils nous transmettent un identifiant de compte, votre nom et votre adresse e-mail.","**Utilisation sans compte :** les favoris, les listes, les recherches récentes, les préférences et votre choix concernant les statistiques restent sur votre appareil. Ils ne quittent pas votre appareil, sauf si, après vous être connecté, vous choisissez de les importer dans votre compte, et hormis les statistiques facultatives ci-dessous (par exemple le geste que vous avez regardé ou enregistré).","**Fonctions d''apprentissage :** gestes favoris, listes, descriptions de listes, liens de partage et leurs droits (consulter ou modifier). Les termes de recherche récents restent localement sur votre appareil.","**Parrainage :** nom de contact, nom du sponsor ou de l''entreprise, e-mail, gestes choisis, nom affiché, logo facultatif, vidéos d''aperçu et finales, statut, référence de paiement et durée.","**Facturation :** nom de facturation, numéro de TVA ou d''entreprise et adresse e-mail de facturation lorsque vous demandez une facture. Mollie traite les données de paiement ; SMOG&Co ne reçoit pas les données complètes de carte ou de compte bancaire.","**Données techniques :** adresse IP, données de l''appareil, du navigateur et de l''application, journaux de sécurité, informations d''erreur et données nécessaires à la diffusion des vidéos et au trafic réseau. Lors de la connexion, de l''inscription, de la réinitialisation du mot de passe et d''autres formulaires (comme la demande d''un code ou d''un lien de connexion), Cloudflare Turnstile vérifie que la demande provient d''un humain.","**Historique du consentement :** lorsque vous êtes connecté, nous conservons vos choix concernant les statistiques (oui ou non, moment et version de la politique), afin de pouvoir démontrer quel choix s''applique.","**Statistiques facultatives :** uniquement avec votre consentement : chemin de l''écran, plateforme, données d''événement limitées, identifiants de gestes, nombres de résultats et de catégories, longueur d''une recherche et lecture terminée, avec votre adresse IP et les données de votre navigateur ou de l''application (voir Statistiques et identification). Nous n''envoyons ni termes de recherche, ni noms, ni adresses e-mail et n''enregistrons pas les sessions."]}],"id":"data","title":"Quelles données nous traitons"},{"blocks":[{"list":["**Contrat :** fournir les comptes, les favoris, les listes, les listes partagées, le parrainage, les paiements, le traitement des vidéos et la communication transactionnelle.","**Obligation légale :** comptabilité, facturation, obligations fiscales et réponse aux demandes légales valables.","**Intérêt légitime :** sécurité, prévention de la fraude et des abus (comme Turnstile et des limites au nombre de requêtes), administration, diagnostic des erreurs et amélioration de la fiabilité du Service. Vous pouvez vous y opposer.","**Consentement :** statistiques OpenPanel facultatives. Vous pouvez refuser ou retirer votre consentement plus tard sans perdre les fonctions de base."]}],"id":"purposes","title":"Finalités et bases juridiques"},{"blocks":["Seuls les collaborateurs autorisés et les prestataires qui soutiennent le Service y ont accès, dans la mesure nécessaire :",{"list":["**Cloudflare :** hébergement du site web et de l''API (Workers), de la base de données (D1), stockage de fichiers comme les logos des sponsors (R2), données temporaires (KV), files d''attente (Queues), génération des vidéos de parrainage avec le nom et le logo (Workflows, Containers), envoi des e-mails (Email) et prévention des abus (Turnstile). [Politique de confidentialité](https://www.cloudflare.com/privacypolicy/)","**Better Auth :** logiciel de connexion open source que nous faisons fonctionner nous-mêmes dans notre environnement Cloudflare. Aucune donnée n''est envoyée à un prestataire distinct pour cela.","**Mux :** stockage, traitement et diffusion des vidéos de gestes et de parrainage. [Politique de confidentialité](https://www.mux.com/privacy)","**Mollie :** traitement hébergé des paiements et statut des paiements. [Politique de confidentialité](https://www.mollie.com/legal/privacy)","**Expo :** distribution et mises à jour de l''application mobile. [Politique de confidentialité](https://expo.dev/privacy)","**Google et Apple :** lorsque vous choisissez de vous connecter avec votre compte Google ou Apple. Si vous avez une photo de profil Google, votre navigateur la récupère directement auprès de Google à chaque affichage ; Google voit votre adresse IP et les données de votre navigateur. [Google](https://policies.google.com/privacy) · [Apple](https://www.apple.com/legal/privacy/)","**OpenPanel :** logiciel de statistiques auto-hébergé sur analytics.zias.be, uniquement avec le consentement aux statistiques. Le cloud OpenPanel n''est pas utilisé pour nos données d''événements."]},"Les données personnelles ne sont pas vendues. Nous ne les partageons que sur la base d''un contrat, d''une obligation légale ou d''un autre cadre juridique valable."],"id":"recipients","title":"Destinataires et prestataires"},{"blocks":["Les statistiques sont désactivées par défaut. Avec votre consentement, le site web transmet les événements par notre propre serveur à notre installation OpenPanel auto-hébergée, sans scripts ni cookies de tiers. Notre serveur transmet votre adresse IP et les données de votre navigateur (user agent) ; OpenPanel en déduit un profil d''appareil pseudonyme et une localisation approximative (pays et région). Notre serveur ne conserve pas ces données à cette fin. L''application envoie les événements directement à la même installation OpenPanel, avec un identifiant d''appareil pseudonyme. Après la connexion, le profil n''est lié qu''à votre identifiant d''utilisateur ; votre nom et votre adresse e-mail ne sont pas envoyés aux statistiques. La déconnexion ou le retrait du consentement efface l''identité statistique. Le retrait arrête les nouvelles mesures ; les données collectées légalement auparavant ne sont pas supprimées automatiquement. Vous pouvez en demander la suppression à notre adresse de contact."],"id":"analytics","title":"Statistiques et identification"},{"blocks":["SMOG & Co ne suit pas les utilisateurs à travers les applications ou sites web d''autres entreprises. Nous n''utilisons pas les données statistiques pour de la publicité ciblée ou la mesure publicitaire et ne partageons pas les données statistiques avec des courtiers en données."],"id":"no-tracking","title":"Pas de pistage ni de publicité"},{"blocks":[{"list":["Des cookies nécessaires maintiennent votre session active lorsque vous êtes connecté et retiennent votre langue et votre thème. Nous plaçons aussi un cookie technique pour les administrateurs pendant une maintenance, afin qu''ils puissent continuer à utiliser le site.","Le stockage local conserve notamment les favoris et les listes sans compte, les recherches récentes, les préférences, le cache de l''application et votre choix concernant les statistiques. Un choix fait en étant connecté reste aussi sur l''appareil, mais ne vaut que pour votre compte : la personne qui utilise ensuite l''appareil sans compte est de nouveau interrogée.","Avec le consentement aux statistiques, l''application peut conserver localement des données d''identification et de file d''attente pour transmettre les événements. Le site web ne conserve qu''un marqueur temporaire dans le stockage de session de votre navigateur pendant la connexion, afin qu''une connexion réussie soit comptée une seule fois."]},"Vous pouvez modifier votre choix concernant les statistiques ci-dessous à tout moment :",{"consentControl":true}],"id":"cookies","title":"Cookies et stockage local"},{"blocks":[{"list":["Les données du compte, les favoris, les listes et votre historique du consentement sont conservés tant que votre compte existe ou jusqu''à ce que vous les supprimiez.","Les journaux d''administration sont conservés au maximum 3 ans.","Une session expire 7 jours après votre dernière utilisation du Service, ou immédiatement lorsque vous vous déconnectez. Les codes et liens de connexion sont à usage unique et valables 5 minutes ; les liens de vérification de l''adresse e-mail ou de réinitialisation du mot de passe, 1 heure. Les sessions, codes et liens expirés sont effacés dans les 30 jours.","Les demandes de parrainage non payées sont annulées après 24 heures. Les fichiers techniques sous-jacents peuvent disparaître plus tard, selon les cycles opérationnels de sauvegarde et de nettoyage.","Les données de paiement, de sponsor et de facturation sont conservées aussi longtemps que nécessaire pour le contrat et jusqu''à 10 ans lorsque les règles comptables ou fiscales belges l''exigent.","Les données statistiques sont conservées selon la durée de conservation définie dans notre installation OpenPanel et pas plus longtemps que nécessaire pour l''analyse du produit."]}],"id":"retention","title":"Durées de conservation"},{"blocks":["Vous pouvez supprimer votre compte sur la [page du compte](/account). Cela supprime immédiatement votre compte, vos sessions, vos méthodes de connexion et clés d''accès, vos favoris, vos propres listes avec leurs liens de partage et votre historique du consentement. Dans les journaux d''administration, vous êtes détaché en tant qu''auteur ; les journaux d''administration concernant votre compte subsistent jusqu''à la fin de leur durée de conservation. Vous êtes déconnecté sur tous les appareils et les données de l''appareil utilisé sont effacées. Les données de sponsor, de paiement et de facturation ne sont pas liées à votre compte et sont conservées aussi longtemps que la loi l''exige (voir Durées de conservation). Les sauvegardes et les données chez des prestataires distincts peuvent suivre leur propre cycle de suppression."],"id":"deletion","title":"Suppression du compte"},{"blocks":["En vertu du RGPD, vous pouvez, selon les circonstances, demander l''accès, la rectification, l''effacement, la limitation, la portabilité ou vous opposer au traitement. Vous pouvez toujours retirer votre consentement et introduire une plainte auprès d''une autorité de contrôle. La [page du compte](/account) propose une exportation lisible par machine (JSON) et la suppression du compte. Pour les autres demandes, écrivez à [info@smog.vlaanderen](mailto:info@smog.vlaanderen). Nous pouvons demander des informations pour vérifier votre identité."],"id":"rights","title":"Vos droits"},{"blocks":["Certains prestataires peuvent traiter des données personnelles en dehors de l''Espace économique européen. Si nécessaire, nous utilisons une décision d''adéquation, des clauses contractuelles types ou un autre mécanisme de transfert valable, ainsi que des mesures de sécurité supplémentaires appropriées."],"id":"transfers","title":"Transferts internationaux"},{"blocks":["Nous utilisons des mesures techniques et organisationnelles appropriées, dont la limitation des accès, des connexions chiffrées, des mots de passe hachés et des secrets protégés. Aucun système n''est entièrement sans risque. En cas d''incident à notifier, nous informons l''autorité compétente et, si nécessaire, les personnes concernées."],"id":"security","title":"Sécurité et incidents"},{"blocks":["En Belgique, un enfant de 13 ans ou plus peut donner lui-même son consentement pour un service en ligne qui lui est proposé directement. Si le droit applicable exige le consentement d''un parent ou d''un tuteur, celui-ci doit être obtenu. Contactez-nous si vous pensez que les données d''un enfant ont été traitées de manière illicite."],"id":"children","title":"Enfants"},{"blocks":["Nous pouvons mettre à jour cette politique lorsque le Service, les fournisseurs ou la législation changent. La date en haut de la page est adaptée et nous informons les utilisateurs des changements importants dans l''application ou par un canal approprié. Si nécessaire, nous demandons à nouveau votre consentement."],"id":"changes","title":"Modifications"},{"blocks":[{"lines":["SMOG & CO vzw","Arthur Goemaerelei 66, 2018 Anvers, Belgique","E-mail : [info@smog.vlaanderen](mailto:info@smog.vlaanderen)","Tél. : +32 3 216 29 90","Numéro d''entreprise 1009 954 991"]},"Vous pouvez aussi introduire une plainte auprès de l''[Autorité de protection des données belge](https://www.autoriteprotectiondonnees.be) ou de votre autorité de contrôle locale."],"id":"contact","title":"Contact et plainte"}],"title":"Politique de confidentialité"}', '2026-09-30', 'published', NULL, 1790726400000, NULL, 1790726400000);
--> statement-breakpoint
INSERT INTO `legal_text` (`id`, `kind`, `locale`, `version`, `content`, `effective_date`, `status`, `updated_by`, `updated_at`, `published_by`, `published_at`) VALUES ('legal-terms-nl-1', 'terms', 'nl', 1, '{"sections":[{"blocks":["Deze voorwaarden gelden voor de SMOG&Co-website, mobiele app, accounts, lijsten, sponsoring en bijbehorende diensten (de \"Dienst\"), aangeboden door SMOG & CO vzw, Arthur Goemaerelei 66, 2018 Antwerpen, België, O.N. 1009 954 991. Door de Dienst te gebruiken gaat u akkoord met deze voorwaarden. Dwingend consumentenrecht blijft altijd gelden."],"id":"provider","title":"Toepassing en aanbieder"},{"blocks":["De Dienst biedt een bibliotheek met gebarenvideo''s, zoeken en filteren, favorieten, eigen en gedeelde lijsten, gebruik zonder account, accountsynchronisatie en de mogelijkheid om een gebaar te sponsoren. Functies kunnen per platform verschillen."],"id":"service","title":"Beschrijving van de Dienst"},{"blocks":["U kunt een account aanmaken met uw e-mailadres (met een wachtwoord, een code of een aanmeldlink), een passkey, of uw Google- of Apple-account. U moet correcte informatie verstrekken, uw account beveiligen en misbruik melden. Zonder account worden favorieten en lijsten alleen op uw apparaat bewaard; ze verdwijnen wanneer u de gegevens van uw browser of app wist. Na het aanmelden kunt u ze in uw account importeren. Een lijst delen vereist een account. U kunt uw account verwijderen via de accountpagina; wettelijke bewaarplichten en afzonderlijke sponsortransacties kunnen verdere bewaring vereisen."],"id":"accounts","title":"Accounts en gebruik zonder account"},{"blocks":["U mag de Dienst niet gebruiken om:",{"list":["de wet of rechten van anderen te schenden;","ongeautoriseerde toegang te verkrijgen of beveiliging te omzeilen;","de Dienst, infrastructuur of andere gebruikers te verstoren;","zonder toestemming geautomatiseerd grote hoeveelheden inhoud op te vragen, te kopiëren of door te verkopen;","misleidende, schadelijke of inbreukmakende sponsorinhoud aan te leveren."]},"We kunnen toegang beperken of beëindigen wanneer dat redelijk nodig is voor beveiliging, wettelijke naleving of een ernstige schending."],"id":"use","title":"Toegestaan gebruik"},{"blocks":["De Dienst, software, teksten, vormgeving en gebarenvideo''s zijn eigendom van SMOG&Co of haar licentiegevers. U krijgt een beperkte, herroepbare, niet-exclusieve en niet-overdraagbare licentie voor persoonlijk en educatief gebruik. Normale browser- of appcaching is toegestaan; downloaden, herpubliceren, wijzigen, commercieel exploiteren of een afgeleid videoproduct maken vereist voorafgaande toestemming, behalve waar de wet dit uitdrukkelijk toestaat."],"id":"ip","title":"Intellectuele eigendom"},{"blocks":[{"list":["Een sponsoring koppelt de gekozen sponsornaam, tekst en eventueel logo gedurende de getoonde looptijd aan een of meer gebarenvideo''s.","De prijs, looptijd en eventuele logo-opslag worden vóór betaling getoond. De server controleert het verschuldigde bedrag. Een sponsoraanvraag is pas betaald nadat Mollie de betaling bevestigt.","SMOG&Co beoordeelt de gesponsorde video vóór publicatie en kan inhoud weigeren die onwettig, misleidend, schadelijk, ongepast of technisch onbruikbaar is. We nemen bij afwijzing contact op over aanpassing of een passende afhandeling van de betaling.","U garandeert dat u de nodige rechten en toestemmingen bezit voor namen, merken, logo''s, tekst en andere aangeleverde inhoud. U verleent SMOG&Co voor de uitvoering van de sponsoring een niet-exclusieve licentie om die inhoud te verwerken, te renderen, te hosten en te tonen.","Voorbeeld- en eindvideo''s kunnen technisch worden aangepast voor formaat, leesbaarheid en streaming. Een door SMOG&Co verstrekte herbewerkingslink is persoonlijk, 7 dagen geldig en mag niet worden gedeeld.","Ongeveer 30 dagen voor het einde van de looptijd ontvangt u een e-mail met een link om de sponsoring te verlengen. Een verlenging is een nieuwe betaling voor een extra jaar tegen de dan getoonde prijs; een sponsoring wordt nooit automatisch verlengd.","Onbetaalde aanvragen kunnen na 24 uur worden geannuleerd. Voor annulering, terugbetaling of een foutieve betaling neemt u contact op; wettelijke consumentenrechten blijven van toepassing."]}],"id":"sponsoring","title":"Sponsoring"},{"blocks":["Betalingen verlopen via de gehoste betaalomgeving van Mollie en zijn onderworpen aan de voorwaarden van de gekozen betaalmethode. U bent verantwoordelijk voor correcte contact- en factuurgegevens. Eventuele belastingen worden toegepast zoals wettelijk vereist. Bij een betwiste, teruggedraaide of frauduleuze betaling mogen we de sponsoring opschorten terwijl de zaak wordt onderzocht."],"id":"payment","title":"Betaling en facturatie"},{"blocks":["Ons [privacybeleid](/privacy) legt uit welke gegevens nodig zijn voor de Dienst en welke verwerking op een andere rechtsgrond berust. Optionele analytics wordt alleen na afzonderlijke toestemming ingeschakeld; gebruik van de Dienst geldt niet als analytics-toestemming."],"id":"privacy","title":"Privacy"},{"blocks":["We streven naar een betrouwbare en correcte Dienst, maar garanderen geen ononderbroken beschikbaarheid of foutloze inhoud. Gebarengebruik kan per regio, persoon en context verschillen. De Dienst is een educatief hulpmiddel en geen professionele certificering, medische dienst of vervanging voor persoonlijk advies."],"id":"availability","title":"Beschikbaarheid en educatieve inhoud"},{"blocks":["Voor zover wettelijk toegestaan is SMOG&Co niet aansprakelijk voor indirecte schade, gevolgschade of verlies dat niet redelijk voorzienbaar was. Niets in deze voorwaarden beperkt aansprakelijkheid die wettelijk niet kan worden uitgesloten, waaronder aansprakelijkheid voor opzet of zware fout waar het toepasselijke recht dat bepaalt. Consumenten behouden hun dwingendrechtelijke remedies."],"id":"liability","title":"Aansprakelijkheid"},{"blocks":["U blijft verantwoordelijk voor inhoud die u aanlevert. Voor zover wettelijk toegestaan, vergoedt een zakelijke gebruiker SMOG&Co voor aanspraken van derden die rechtstreeks voortvloeien uit opzettelijk onrechtmatig gebruik of uit aangeleverde sponsorinhoud waarvoor die gebruiker de vereiste rechten niet bezit. Deze bepaling beperkt geen wettelijke consumentenbescherming."],"id":"indemnity","title":"Inhoud van gebruikers en schadeloosstelling"},{"blocks":["We kunnen functies wijzigen, onderhouden of stopzetten. Bij een belangrijke wijziging die een lopende betaalde sponsoring wezenlijk raakt, zoeken we een redelijke oplossing. We kunnen deze voorwaarden aanpassen en vermelden steeds de nieuwe datum. Voor wezenlijke wijzigingen informeren we gebruikers via de Dienst of een passend contactkanaal."],"id":"changes","title":"Wijzigingen en stopzetting"},{"blocks":["Belgisch recht is van toepassing. Geschillen behoren tot de bevoegde Belgische rechtbanken, behalve wanneer dwingend consumentenrecht u het recht geeft een andere bevoegde rechtbank te kiezen. Probeer een probleem eerst via [info@smog.vlaanderen](mailto:info@smog.vlaanderen) met ons op te lossen."],"id":"law","title":"Toepasselijk recht en geschillen"},{"blocks":["Als een bepaling ongeldig of onafdwingbaar is, blijven de overige bepalingen gelden. Het niet onmiddellijk afdwingen van een recht is geen afstand daarvan. Deze voorwaarden en het privacybeleid vormen de afspraken over het gebruik van de Dienst, naast specifieke informatie die bij een aankoop wordt getoond."],"id":"general","title":"Overige bepalingen"},{"blocks":[{"lines":["SMOG & CO vzw","Arthur Goemaerelei 66, 2018 Antwerpen, België","E-mail: [info@smog.vlaanderen](mailto:info@smog.vlaanderen)","Tel.: 03/216 29 90","O.N. 1009 954 991"]}],"id":"contact","title":"Contact"}],"title":"Servicevoorwaarden"}', '2026-09-30', 'published', NULL, 1790726400000, NULL, 1790726400000);
--> statement-breakpoint
INSERT INTO `legal_text` (`id`, `kind`, `locale`, `version`, `content`, `effective_date`, `status`, `updated_by`, `updated_at`, `published_by`, `published_at`) VALUES ('legal-terms-en-1', 'terms', 'en', 1, '{"sections":[{"blocks":["These terms apply to the SMOG&Co website, mobile app, accounts, lists, sponsorship and related services (the \"Service\"), offered by SMOG & CO vzw, Arthur Goemaerelei 66, 2018 Antwerp, Belgium, company number 1009 954 991. By using the Service you agree to these terms. Mandatory consumer law always continues to apply."],"id":"provider","title":"Application and provider"},{"blocks":["The Service offers a library of gesture videos, search and filters, favorites, your own and shared lists, use without an account, account synchronisation and the option to sponsor a gesture. Features may differ per platform."],"id":"service","title":"Description of the Service"},{"blocks":["You can create an account with your email address (with a password, a code or a sign-in link), a passkey, or your Google or Apple account. You must provide correct information, keep your account secure and report misuse. Without an account, favorites and lists are only kept on your device; they disappear when you clear your browser or app data. After signing in you can import them into your account. Sharing a list requires an account. You can delete your account on the account page; legal retention obligations and separate sponsorship transactions may require further retention."],"id":"accounts","title":"Accounts and use without an account"},{"blocks":["You may not use the Service to:",{"list":["break the law or infringe the rights of others;","gain unauthorised access or circumvent security;","disrupt the Service, its infrastructure or other users;","request, copy or resell large amounts of content by automated means without permission;","submit misleading, harmful or infringing sponsorship content."]},"We may restrict or end access when reasonably needed for security, legal compliance or a serious breach."],"id":"use","title":"Permitted use"},{"blocks":["The Service, software, texts, design and gesture videos are owned by SMOG&Co or its licensors. You get a limited, revocable, non-exclusive and non-transferable licence for personal and educational use. Normal browser or app caching is allowed; downloading, republishing, modifying, commercially exploiting or making a derived video product requires prior permission, except where the law expressly allows it."],"id":"ip","title":"Intellectual property"},{"blocks":[{"list":["A sponsorship links the chosen sponsor name, text and optional logo to one or more gesture videos for the term shown.","The price, term and any logo surcharge are shown before payment. The server checks the amount due. A sponsorship request only counts as paid once Mollie confirms the payment.","SMOG&Co reviews the sponsored video before publication and may refuse content that is unlawful, misleading, harmful, inappropriate or technically unusable. If we refuse it, we contact you about changes or an appropriate handling of the payment.","You guarantee that you hold the necessary rights and permissions for names, brands, logos, text and other submitted content. For carrying out the sponsorship, you grant SMOG&Co a non-exclusive licence to process, render, host and show that content.","Preview and final videos may be adjusted technically for format, legibility and streaming. A re-edit link provided by SMOG&Co is personal, valid for 7 days and may not be shared.","About 30 days before the end of the term you receive an email with a link to renew the sponsorship. A renewal is a new payment for one more year at the price then shown; a sponsorship is never renewed automatically.","Unpaid requests may be cancelled after 24 hours. For cancellation, a refund or a wrong payment, contact us; statutory consumer rights continue to apply."]}],"id":"sponsoring","title":"Sponsorship"},{"blocks":["Payments go through Mollie''s hosted payment environment and are subject to the terms of the chosen payment method. You are responsible for correct contact and invoice details. Any taxes are applied as required by law. In case of a disputed, reversed or fraudulent payment, we may suspend the sponsorship while the matter is investigated."],"id":"payment","title":"Payment and invoicing"},{"blocks":["Our [privacy policy](/privacy) explains which data the Service needs and which processing rests on another legal basis. Optional analytics is only switched on after separate consent; using the Service does not count as analytics consent."],"id":"privacy","title":"Privacy"},{"blocks":["We aim for a reliable and correct Service, but do not guarantee uninterrupted availability or error-free content. The use of gestures may differ per region, person and context. The Service is an educational tool and not a professional certification, a medical service or a replacement for personal advice."],"id":"availability","title":"Availability and educational content"},{"blocks":["As far as the law allows, SMOG&Co is not liable for indirect damage, consequential damage or loss that was not reasonably foreseeable. Nothing in these terms limits liability that cannot be excluded by law, including liability for intent or gross negligence where the applicable law provides so. Consumers keep their mandatory legal remedies."],"id":"liability","title":"Liability"},{"blocks":["You remain responsible for content you submit. As far as the law allows, a business user compensates SMOG&Co for third-party claims that arise directly from intentionally unlawful use or from submitted sponsorship content for which that user does not hold the required rights. This clause does not limit statutory consumer protection."],"id":"indemnity","title":"User content and indemnity"},{"blocks":["We may change, maintain or discontinue features. If an important change materially affects a running paid sponsorship, we look for a reasonable solution. We may amend these terms and always state the new date. We inform users of material changes through the Service or an appropriate contact channel."],"id":"changes","title":"Changes and discontinuation"},{"blocks":["Belgian law applies. Disputes fall under the competent Belgian courts, except where mandatory consumer law gives you the right to choose another competent court. Please first try to solve a problem with us through [info@smog.vlaanderen](mailto:info@smog.vlaanderen)."],"id":"law","title":"Applicable law and disputes"},{"blocks":["If a provision is invalid or unenforceable, the other provisions remain in force. Not enforcing a right immediately is not a waiver of it. These terms and the privacy policy form the agreement on the use of the Service, alongside specific information shown with a purchase."],"id":"general","title":"Other provisions"},{"blocks":[{"lines":["SMOG & CO vzw","Arthur Goemaerelei 66, 2018 Antwerp, Belgium","Email: [info@smog.vlaanderen](mailto:info@smog.vlaanderen)","Phone: +32 3 216 29 90","Company number 1009 954 991"]}],"id":"contact","title":"Contact"}],"title":"Terms of service"}', '2026-09-30', 'published', NULL, 1790726400000, NULL, 1790726400000);
