INSERT INTO `legal_text` (`id`, `kind`, `locale`, `version`, `content`, `effective_date`, `status`, `updated_by`, `updated_at`, `published_by`, `published_at`) VALUES ('legal-terms-fr-1', 'terms', 'fr', 1, '{"sections":[{"blocks":["Les présentes conditions s''appliquent au site web SMOG&Co, à l''application mobile, aux comptes, aux listes, au parrainage et aux services associés (le « Service »), proposés par SMOG & CO vzw, Arthur Goemaerelei 66, 2018 Anvers, Belgique, numéro d''entreprise 1009 954 991. En utilisant le Service, vous acceptez ces conditions. Le droit impératif de la consommation reste toujours applicable."],"id":"provider","title":"Application et prestataire"},{"blocks":["Le Service propose une bibliothèque de vidéos de gestes, la recherche et les filtres, les favoris, vos propres listes et des listes partagées, l''utilisation sans compte, la synchronisation du compte et la possibilité de parrainer un geste. Les fonctions peuvent différer selon la plateforme."],"id":"service","title":"Description du Service"},{"blocks":["Vous pouvez créer un compte avec votre adresse e-mail (avec un mot de passe, un code ou un lien de connexion), une clé d''accès (passkey), ou votre compte Google ou Apple. Vous devez fournir des informations correctes, sécuriser votre compte et signaler les abus. Sans compte, les favoris et les listes ne sont conservés que sur votre appareil ; ils disparaissent lorsque vous effacez les données de votre navigateur ou de l''application. Après la connexion, vous pouvez les importer dans votre compte. Partager une liste nécessite un compte. Vous pouvez supprimer votre compte sur la page du compte ; des obligations légales de conservation et des transactions de parrainage distinctes peuvent exiger une conservation plus longue."],"id":"accounts","title":"Comptes et utilisation sans compte"},{"blocks":["Vous ne pouvez pas utiliser le Service pour :",{"list":["enfreindre la loi ou les droits d''autrui ;","obtenir un accès non autorisé ou contourner la sécurité ;","perturber le Service, l''infrastructure ou d''autres utilisateurs ;","demander, copier ou revendre de grandes quantités de contenu de manière automatisée sans autorisation ;","fournir un contenu de parrainage trompeur, nuisible ou contrefaisant."]},"Nous pouvons limiter ou mettre fin à l''accès lorsque cela est raisonnablement nécessaire pour la sécurité, le respect de la loi ou une violation grave."],"id":"use","title":"Utilisation autorisée"},{"blocks":["Le Service, les logiciels, les textes, la conception et les vidéos de gestes appartiennent à SMOG&Co ou à ses concédants. Vous obtenez une licence limitée, révocable, non exclusive et non transférable pour un usage personnel et éducatif. La mise en cache normale par le navigateur ou l''application est autorisée ; le téléchargement, la republication, la modification, l''exploitation commerciale ou la création d''un produit vidéo dérivé nécessitent une autorisation préalable, sauf lorsque la loi le permet expressément."],"id":"ip","title":"Propriété intellectuelle"},{"blocks":[{"list":["Un parrainage associe le nom du sponsor, le texte et éventuellement le logo choisis à une ou plusieurs vidéos de gestes pendant la durée indiquée.","Le prix, la durée et l''éventuel supplément pour le logo sont indiqués avant le paiement. Le serveur vérifie le montant dû. Une demande de parrainage n''est considérée comme payée qu''une fois le paiement confirmé par Mollie.","SMOG&Co examine la vidéo parrainée avant sa publication et peut refuser un contenu illicite, trompeur, nuisible, inapproprié ou techniquement inutilisable. En cas de refus, nous vous contactons au sujet d''une modification ou d''un traitement approprié du paiement.","Vous garantissez que vous disposez des droits et autorisations nécessaires pour les noms, marques, logos, textes et autres contenus fournis. Pour l''exécution du parrainage, vous accordez à SMOG&Co une licence non exclusive pour traiter, générer, héberger et afficher ce contenu.","Les vidéos d''aperçu et finales peuvent être adaptées techniquement pour le format, la lisibilité et la diffusion. Un lien de modification fourni par SMOG&Co est personnel, valable 7 jours et ne peut pas être partagé.","Environ 30 jours avant la fin de la durée, vous recevez un e-mail avec un lien pour renouveler le parrainage. Un renouvellement est un nouveau paiement pour une année supplémentaire au prix alors indiqué ; un parrainage n''est jamais renouvelé automatiquement.","Les demandes non payées peuvent être annulées après 24 heures. Pour une annulation, un remboursement ou un paiement erroné, contactez-nous ; les droits légaux des consommateurs restent applicables."]}],"id":"sponsoring","title":"Parrainage"},{"blocks":["Les paiements passent par l''environnement de paiement hébergé de Mollie et sont soumis aux conditions du moyen de paiement choisi. Vous êtes responsable de l''exactitude des données de contact et de facturation. Les éventuelles taxes sont appliquées conformément à la loi. En cas de paiement contesté, annulé ou frauduleux, nous pouvons suspendre le parrainage pendant l''examen de l''affaire."],"id":"payment","title":"Paiement et facturation"},{"blocks":["Notre [politique de confidentialité](/privacy) explique quelles données sont nécessaires au Service et quels traitements reposent sur une autre base juridique. Les statistiques facultatives ne sont activées qu''après un consentement distinct ; l''utilisation du Service ne vaut pas consentement aux statistiques."],"id":"privacy","title":"Vie privée"},{"blocks":["Nous visons un Service fiable et correct, mais ne garantissons ni une disponibilité ininterrompue ni un contenu sans erreur. L''usage des gestes peut varier selon la région, la personne et le contexte. Le Service est un outil éducatif et non une certification professionnelle, un service médical ou un substitut à un conseil personnel."],"id":"availability","title":"Disponibilité et contenu éducatif"},{"blocks":["Dans la mesure permise par la loi, SMOG&Co n''est pas responsable des dommages indirects, des dommages consécutifs ou des pertes qui n''étaient pas raisonnablement prévisibles. Rien dans ces conditions ne limite une responsabilité qui ne peut pas être exclue par la loi, notamment la responsabilité pour faute intentionnelle ou faute grave lorsque le droit applicable le prévoit. Les consommateurs conservent leurs recours légaux impératifs."],"id":"liability","title":"Responsabilité"},{"blocks":["Vous restez responsable du contenu que vous fournissez. Dans la mesure permise par la loi, un utilisateur professionnel indemnise SMOG&Co des réclamations de tiers qui résultent directement d''une utilisation intentionnellement illicite ou d''un contenu de parrainage fourni pour lequel cet utilisateur ne dispose pas des droits requis. Cette disposition ne limite pas la protection légale des consommateurs."],"id":"indemnity","title":"Contenu des utilisateurs et indemnisation"},{"blocks":["Nous pouvons modifier, entretenir ou arrêter des fonctions. Si un changement important affecte substantiellement un parrainage payé en cours, nous cherchons une solution raisonnable. Nous pouvons adapter ces conditions et indiquons toujours la nouvelle date. Nous informons les utilisateurs des changements substantiels par le Service ou un canal de contact approprié."],"id":"changes","title":"Modifications et arrêt"},{"blocks":["Le droit belge est applicable. Les litiges relèvent des tribunaux belges compétents, sauf lorsque le droit impératif de la consommation vous donne le droit de choisir un autre tribunal compétent. Essayez d''abord de résoudre un problème avec nous via [info@smog.vlaanderen](mailto:info@smog.vlaanderen)."],"id":"law","title":"Droit applicable et litiges"},{"blocks":["Si une disposition est invalide ou inapplicable, les autres dispositions restent en vigueur. Le fait de ne pas faire valoir immédiatement un droit ne constitue pas une renonciation à celui-ci. Ces conditions et la politique de confidentialité constituent les accords sur l''utilisation du Service, en plus des informations spécifiques affichées lors d''un achat."],"id":"general","title":"Autres dispositions"},{"blocks":[{"lines":["SMOG & CO vzw","Arthur Goemaerelei 66, 2018 Anvers, Belgique","E-mail : [info@smog.vlaanderen](mailto:info@smog.vlaanderen)","Tél. : +32 3 216 29 90","Numéro d''entreprise 1009 954 991"]}],"id":"contact","title":"Contact"}],"title":"Conditions d''utilisation"}', '2026-09-30', 'published', NULL, 1790726400000, NULL, 1790726400000);
